"""Summarize completed checks without changing the runtime package."""
import hashlib,json,sys
from pathlib import Path
sys.dont_write_bytecode=True
ROOT=Path(__file__).resolve().parents[1];E=ROOT/'evidence'
def read(n):return json.loads((E/n).read_text())
def save(n,v):(E/n).write_text(json.dumps(v,indent=2)+'\n')
before=read('shortcut-before.json');after=read('shortcut-after.json');ui=read('ui-order-results.json')
probes=[]
for name,reports in [('before',before),('after',after)]:
 for profile,report in reports.items():
  for cue,counts in report['cues'].items():
   probes.append({'cue':'candidate position or candidate-bank geometry','subgroup':name+':'+profile,'scope':'within_template','strategy':cue,'correct':counts['successes'],'total':counts['attempts'],'baseline':.2,'disposition':'not_predictive','conclusion':'Each strategy has independently verified counterexamples within this profile; five eligible candidate roles were exercised. This finite probe does not exclude all possible shortcuts.','sample_refs':['shortcut-'+name+'.json','controlled-records.json' if name=='before' else 'delivery/accepted.json']})
for stage,counts in ui['counts'].items():
 for profile in ['q-20598','q-20589']:
  c=counts[profile];probes.append({'cue':'actual UI position','subgroup':stage+':'+profile,'scope':'within_template','strategy':'Most frequent displayed correct position, chosen retrospectively','correct':max(c.values()),'total':sum(c.values()),'baseline':.2,'disposition':'not_predictive','conclusion':'No position is universally correct. Exact UI choiceOrder executed and checked against five DOM fixtures. Production task IDs are unavailable.','sample_refs':['ui-order-results.json']})
variation={'learner_operation':'Construct the augmented matrix, eliminate above the third and second pivots, and identify its unique RREF or ordered solution.','fixed_features':[{'feature':'Upper triangular full-rank 3x3 system with unit pivots, integer arithmetic, variables x/y/z','justification':'Target knowledge point assesses backward elimination rather than forward elimination or singular systems. Unit pivots keep the two/three-row-addition easy practice workload observed in every source practice case.'},{'feature':'One five-choice radio field for practice; fieldless canonical replay excluded from sampling','justification':'Exactly one candidate solves the nonsingular system. Preserve complete captured practice banks and do not invent an uncaptured canonical bank.'}],'answer_roles':[{'role':'Which candidate triple solves the system','eligible_variation':'Any of five distinct candidates can be correct when RHS is derived from that candidate.','observed':'All five tested roles in each restored profile and one prior profile per response shape; all survive filtering.'},{'role':'Which above-pivot entries need elimination','eligible_variation':'All three nonzero, or each one individually absent, with signed coefficients.','observed':'Four declared masks in each of five controlled profiles; independent visible row-operation validation.'}],'coverage':[{'case':'Restored source replay and preserved complete banks','sample_refs':['source-replay.json','source-replay-records.json'],'result':'15 captured cases replay, all 14 practice banks match all 70 original choices, canonical has no invented bank; all captured operative solution stages match.'},{'case':'Within-profile answer roles and elimination masks','sample_refs':['controlled-records.json','shortcut-before.json','shortcut-after.json'],'result':'25 controlled semantic records across five profiles, five different solutions and four masks per profile; all survive shared delivery. Existing variation methods were retained.'},{'case':'Small seeded sampler and relocation','sample_refs':['sample-records.json','packaging.json'],'result':'Five seeded records repeat exactly after relocation with only declared runtime files.'}],'counterfactuals':[{'kind':kind,'change':change,'expected':expected,'observed':'Three response-shape pairs pass independent visible mathematics and actual native all-choice grading. Representative matrix/text pairs and vector representation rendered in the unmodified UI.','status':'passed','justification':why,'sample_refs':['counterfactual-results.json','counterfactual-records.json','grader-results.json','render/rendering.json','render-delivered/rendering.json']} for kind,change,expected,why in [('relevant','Hold coefficients, bank and seed fixed; change correct candidate role from 0 to 1 and recompute RHS.','Displayed RHS, final RREF, explanation and accepted candidate change together.','A different RHS determines a different unique solution; the source candidate identity has no instructional privilege.'),('irrelevant','Negate above-pivot coefficients while retaining the selected solution; recompute RHS.','Final correct triple remains unchanged while equations, row operations and intermediates change.','Different nonsingular triangular systems can share one solution; equation representation is irrelevant to the final candidate value.')]],'shortcut_probes':probes,'delivery':{'stages_examined':['Generator duplicate rejection and explicit profile separation','Shared prepare_records normalization, validation, deduplication and requested easy band','Captured inventory inspection','Conditional learner selection branches from unchanged question_selection.rs','Actual UI choice ordering before and after normalization'],'sample_refs':['delivery/delivery.json','delivery/accepted.json','selection-analysis.json','inventory-assessment.json','ui-order-results.json'],'result':'39/39 records survive; no tested answer-role or mask support lost. No affected stored generated instance demonstrated for this replay-registry omission. Conditional selection limits recorded.'},'limitations':['q-20589 lacks a captured correct key, worked solution and difficulty; these are explicitly inferred from its equations and target lesson.','Canonical e-4709 has no captured answer bank or difficulty and is evidence-only replay.','No live learner history, active policy or production allocation IDs supplied; weighted-selection conclusions are conditional.','Five non-source inventory records lack generation metadata; provenance and seed reconstruction cannot be established. The omission itself is not a demonstrated per-instance construction failure.','Finite shortcut probes support only tested strategies; recognizing directly supplied z is valid partial elimination.']}
