save('repair-summary.json',{'finding_id':'6f947ef9d75ceb3ab20e','fidelity':{'source_cases':source['passed'],'complete_banks':source['complete_banks'],'choices':source['choices_matched']},'correctness':{'visible_records_independently_checked':math['checked'],'failures':[]},'grading':{'accepted':grade['accepted_checks'],'rejected':grade['rejected_checks'],'unexpected':0},'variation':{'controlled_profiles':5,'roles_per_profile':5,'masks_per_profile':4,'delivered':delivery['accepted_count'],'input':delivery['input_count'],'universal_tested_incidental_predictors':0},'rendering':{'screenshots_inspected':8,'passed':True},'package':'../package.json','no_publication':True,'no_database_writes':True,'limitations':variation['limitations']})
